#pragma once

/// @file tag_family_data.hpp
/// @brief Raw published AprilTag tables, generated (WP-13.7).
///
/// `tag_family_data.cpp` is generated by
/// `tools/markers/import_apriltag_families.py` from the BSD-2-Clause
/// AprilRobotics/apriltag sources. It holds the seven published families'
/// codes and bit layouts verbatim. Nothing outside `tag_families.cpp` should
/// use this header: the public surface is `tag_families.hpp`.

#include <cstdint>
#include <span>
#include <utility>

#include "common/algorithm/markers/tag_families.hpp"

namespace alphashape {

/// One published family exactly as the source file declares it. `codes` is in
/// the published order (so a code's array index is its tag id), and `bit_xy`
/// gives the published `(bit_x, bit_y)` cell for each bit index, most
/// significant code bit first.
struct TagFamilyData {
    const char* name = "";
    int bits = 0;
    int min_hamming = 0;
    int total_width = 0;
    int width_at_border = 0;
    bool reversed_border = false;
    std::span<const std::uint64_t> codes;
    std::span<const std::pair<int, int>> bit_xy;
};

/// Raw data for `family`. The enum order is the generated array order; the
/// function never fails for a valid enum value.
const TagFamilyData& tag_family_data(AprilTagFamily family);

}  // namespace alphashape
